		t.Fatal("reader changed in receipt JSON round trip")
	}
	dumps, replays := 0, 0
	for _, call := range reader615Calls(t, log) {
		if call["dump"] != "" {
			if call["module"] == "Reader615" {
				dumps++
			} else {
				replays++
			}
		}
	}
