			if hard {
				err = os.Link(target, view)
			} else {
				err = os.Symlink(target, view)
			}
			if err != nil {
				t.Fatal(err)
			}
			r := reader615Run(t, dir, tc, true)
			got := reader615RecordOf(t, r)
			if !r.Passed || got.Unavailable == nil || strings.Contains(string(reader615JSON(t, got)), "outside sentinel") {
